package com.reqlens.app;
import android.app.*;import android.graphics.Typeface;import android.os.Bundle;import android.widget.*;
public final class ComparerActivity extends Activity{
 public static String left="",right="";
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(16,16,16,16);TextView t=new TextView(this);t.setText("Comparer");t.setTextSize(22);t.setTypeface(Typeface.DEFAULT_BOLD);r.addView(t);EditText a=new EditText(this),c=new EditText(this);a.setHint("Text A");c.setHint("Text B");a.setMinLines(5);c.setMinLines(5);a.setTypeface(Typeface.MONOSPACE);c.setTypeface(Typeface.MONOSPACE);a.setText(left);c.setText(right);left="";right="";TextView o=new TextView(this);o.setTextIsSelectable(true);o.setTypeface(Typeface.MONOSPACE);Button x=new Button(this);x.setText("COMPARE");x.setOnClickListener(v->o.setText(TextDiff.summarize(a.getText().toString(),c.getText().toString())));Button swap=new Button(this);swap.setText("SWAP");swap.setOnClickListener(v->{String q=a.getText().toString();a.setText(c.getText().toString());c.setText(q);});LinearLayout row=new LinearLayout(this);row.addView(x,new LinearLayout.LayoutParams(0,48,1));row.addView(swap,new LinearLayout.LayoutParams(0,48,1));r.addView(a);r.addView(c);r.addView(row);r.addView(o);setContentView(r);}
}
